#!/bin/sh
# Generated by Strategy for hello -- do not hand-edit
set -eu
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
JAIL=hello
APP=hello
JAIL_IP=10.20.0.2
JROOT="/jails/${JAIL}"
FREEBSD_VERSION="$(freebsd-version -u | cut -d- -f1-2)"
log() { echo "==> [${JAIL}] $*"; }
if [ -d "${JROOT}/opt/${APP}" ] && [ ! -L "${JROOT}/opt/${APP}" ]; then
  echo "${JAIL}: /opt/${APP} is a directory, the old pre-release layout; refusing to bootstrap over it" >&2
  exit 1
fi
service jail stop "$JAIL" 2>/dev/null || true
if [ ! -f "${JROOT}/bin/sh" ]; then
  mkdir -p "$JROOT"
  fetch -o /tmp/base.txz \
    "https://download.freebsd.org/releases/amd64/${FREEBSD_VERSION}/base.txz"
  tar -xpf /tmp/base.txz -C "$JROOT"
  rm /tmp/base.txz
fi
chflags noschg "${JROOT}/etc/resolv.conf" 2>/dev/null || true
echo "nameserver 1.1.1.1" >"${JROOT}/etc/resolv.conf"
chflags schg "${JROOT}/etc/resolv.conf"
cp /etc/localtime "${JROOT}/etc/localtime"
mkdir -p "${JROOT}/opt/.infra-releases" "${JROOT}/var/db/${APP}" \
  "${JROOT}/etc/${APP}" "${JROOT}/var/log/${APP}" "${JROOT}/var/run/${APP}"
grep -q "syslogd_enable" "${JROOT}/etc/rc.conf" 2>/dev/null || cat >>"${JROOT}/etc/rc.conf" <<'EOF'
syslogd_enable="NO"
sendmail_enable="NONE"
EOF
grep -q "^${JAIL}[[:space:]]*{" /etc/jail.conf 2>/dev/null || cat >>/etc/jail.conf <<EOF

${JAIL} {
    path          = /jails/${JAIL};
    host.hostname = ${JAIL}.local;
    ip4.addr      = lo1|${JAIL_IP}/32;
    exec.start    = "/bin/sh /etc/rc";
    exec.stop     = "/bin/sh /etc/rc.shutdown";
    exec.clean;
    mount.devfs;
    allow.raw_sockets = 0;
    allow.sysvipc    = 0;
}
EOF
sysrc -n jail_list | grep -qw "$JAIL" || sysrc jail_list+=" ${JAIL}"
sysrc jail_enable="YES"
service jail start "$JAIL" 2>/dev/null || service jail restart "$JAIL"
jexec "$JAIL" pkg bootstrap -y
jexec "$JAIL" pkg install -y erlang-runtime28 elixir-devel sqlite3 gmake git curl node24 npm-node24
jexec "$JAIL" sh -c 'for b in /usr/local/lib/erlang28/bin/*; do ln -sf "$b" /usr/local/bin/; done'
jexec "hello" pw useradd -n "hello" -d "/var/db/hello" -s /usr/sbin/nologin \
  -c "hello service user" 2>/dev/null || true
jexec "hello" chown -R "hello:hello" "/var/db/hello" "/var/log/hello" "/var/run/hello"
mkdir -p "${JROOT}/usr/local/etc/rc.d"
cat >"${JROOT}/usr/local/etc/rc.d/hello" <<'SERAI_RC'
#!/bin/sh
#
# PROVIDE: hello
# REQUIRE: NETWORKING
# KEYWORD: shutdown
#
# Generated by serai for hello; do not hand-edit.
# shellcheck disable=SC2034 # rc.subr reads these variables

. /etc/rc.subr

name="hello"
rcvar="hello_enable"
load_rc_config "$name"
: "${hello_enable:=NO}"

app_user="hello"
envfile="/etc/hello/env"
logfile="/var/log/hello/hello.log"
start_cmd="hello_start"
stop_cmd="hello_stop"
status_cmd="hello_status"
extra_commands="migrate"
migrate_cmd="hello_migrate"
release_bin="/opt/hello/bin/hello"

# The operator's env.
hello_env() {
    [ -r "$envfile" ] || { echo "$name: cannot read $envfile" >&2; return 1; }
    set -a
    # shellcheck disable=SC1090 # the operator's runtime configuration
    . "$envfile"
    HOME=/var/db/hello
    set +a
    # Every variable the app's env.template declares.
    for var in PHX_SERVER PHX_HOST PORT DATABASE_PATH POOL_SIZE LANG SECRET_KEY_BASE RELEASE_COOKIE RELEASE_TMP; do
        eval "value=\${$var:-}"
        # shellcheck disable=SC2154 # assigned by the eval above
        case "$value" in
            ''|REPLACE_ME) echo "$name: $var is not set in $envfile" >&2; return 1 ;;
        esac
    done
}

hello_dirs() {
    mkdir -p /var/run/hello /var/log/hello
    chown "$app_user" /var/run/hello /var/log/hello
}

# A release needs its distribution cookie for stop and pid as well as start.
hello_release_env() {
    hello_env || return 1
    : "${RELEASE_COOKIE:?$name: RELEASE_COOKIE not set in $envfile}"
    set -a
    RELEASE_TMP=${RELEASE_TMP:-/var/run/hello}
    set +a
}

hello_start() {
    hello_dirs
    hello_release_env || return 1
    su -m "$app_user" -c "$release_bin daemon" </dev/null >>"$logfile" 2>&1
}

hello_stop() {
    hello_release_env || return 1
    su -m "$app_user" -c "$release_bin stop" >>"$logfile" 2>&1 \
        || echo "$name not running"
}

hello_status() {
    hello_release_env || return 1
    pid=$(su -m "$app_user" -c "$release_bin pid" 2>/dev/null)
    if [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null; then
        echo "$name running as PID $pid"
    else
        echo "$name not running"
        return 1
    fi
}

hello_migrate() {
    hello_release_env || return 1
    su -m "$app_user" -c "$release_bin eval 'Hello.Release.migrate()'" </dev/null
}

run_rc_command "$1"
SERAI_RC
chmod 0755 "${JROOT}/usr/local/etc/rc.d/hello"
jexec "$JAIL" sysrc hello_enable="YES"
if jexec "$JAIL" test -f "/etc/${APP}/env"; then
  jexec "$JAIL" chown "root:${APP}" "/etc/${APP}/env"
  jexec "$JAIL" chmod 0640 "/etc/${APP}/env"
else
  log "No /etc/${APP}/env yet: write it from the app's env.template, root:${APP} 0640, before the first activation"
fi